using System.Linq;

namespace Test
{
    public class B {}

    public class C
    {
        public static B b = new B();

        public static implicit operator B(C c)
        {
            return b;
        }
    }

    public class Program
    {
        public static void Main()
        {
            B b = new B();
            C c = new C();

            var a = new [] {b, c};

            System.Console.Write(a.SequenceEqual(new B[]{b, c}));
        }
    }
}
